  },
  {
    id: 'team',
    name: 'Team',
    resources: [
      {
        id: 'members',
        name: 'Members',
        description: 'Invite, change roles and remove',
        actions: ['view', 'create', 'edit', 'delete', 'export'],
      },
      {
