    'subscription.view',
    'subscription.edit',
  ),
  owner: grant(),
}

import { actions, roles } from './data'
import type { Action, Grants, Resource, Role } from './data'

// Every checkbox in the matrix is one of these. Only the stored grants are
// state; whether a cell is inherited, required or locked is worked out from
// them on every render, so editing a parent role updates its children at once.
export type CellState =
  | { kind: 'unavailable' }
  | { kind: 'locked'; role: Role }
  | { kind: 'inherited'; from: Role }
  | { kind: 'required'; by: Action[] }
  | { kind: 'granted' }
  | { kind: 'denied' }

export interface Cell {
  resource: Resource
  action: Action
}

export const key = (resourceId: string, action: Action) =>
  `${resourceId}.${action}`

const roleById = new Map(roles.map((role) => [role.id, role]))
export const getRole = (id: string) => roleById.get(id)!

/** Parent first, then grandparent, and so on */
function ancestors(role: Role): Role[] {
  const chain: Role[] = []
  let parent = role.inherits ? roleById.get(role.inherits) : undefined
  while (parent && !chain.includes(parent)) {
    chain.push(parent)
    parent = parent.inherits ? roleById.get(parent.inherits) : undefined
  }
  return chain
}

/** The nearest ancestor that grants this permission, if any */
function inheritedFrom(role: Role, k: string, grants: Grants) {
  return ancestors(role).find((a) => a.locked || grants[a.id].has(k))
}

export function cellState(
  roleId: string,
  { resource, action }: Cell,
  grants: Grants,
): CellState {
  if (!resource.actions.includes(action)) return { kind: 'unavailable' }
  const role = getRole(roleId)
  if (role.locked) return { kind: 'locked', role }
  const k = key(resource.id, action)
  const from = inheritedFrom(role, k, grants)
  if (from) return { kind: 'inherited', from }
  const own = grants[roleId] ?? new Set<string>()
  if (!own.has(k)) return { kind: 'denied' }
  if (action === 'view') {
    // Every other action needs View, so it stays on while any of them is granted
    const by = resource.actions.filter(
      (a) => a !== 'view' && own.has(key(resource.id, a)),
    )
    if (by.length) return { kind: 'required', by }
  }
  return { kind: 'granted' }
}

export const isOn = (state: CellState) =>
  state.kind !== 'denied' && state.kind !== 'unavailable'

/** Cells this role decides for itself, the ones a bulk toggle may change */
export const isOwn = (state: CellState) =>
  state.kind === 'granted' ||
  state.kind === 'denied' ||
  state.kind === 'required'

/** Grant or revoke several cells for one role, keeping View wherever another action needs it */
export function setCells(
  grants: Grants,
  roleId: string,
  cells: Cell[],
  on: boolean,
): Grants {
  const targets = cells.filter((c) => isOwn(cellState(roleId, c, grants)))
  if (!targets.length) return grants
  const next = new Set(grants[roleId])
  for (const { resource, action } of targets) {
    if (on) next.add(key(resource.id, action))
    else next.delete(key(resource.id, action))
  }
  const resources = new Set(targets.map((c) => c.resource))
  for (const resource of resources) {
    const needsView = resource.actions.some(
      (a) => a !== 'view' && next.has(key(resource.id, a)),
    )
    const viewKey = key(resource.id, 'view')
    const viewInherited = inheritedFrom(getRole(roleId), viewKey, grants)
    if (needsView && !viewInherited) next.add(viewKey)
  }
  return { ...grants, [roleId]: next }
}

export interface Summary {
  checked: boolean | 'indeterminate'
  /** False when none of the cells can be changed for this role */
  enabled: boolean
  /** What clicking the summary checkbox does */
  next: boolean
}

/** The tri-state checkbox for a row, a group or a whole column */
export function summarize(
  roleId: string,
  cells: Cell[],
  grants: Grants,
): Summary {
  const states = cells
    .map((c) => cellState(roleId, c, grants))
    .filter((s) => s.kind !== 'unavailable')
  const on = states.filter(isOn).length
  const own = states.filter(isOwn)
  return {
    checked: on === 0 ? false : on === states.length ? true : 'indeterminate',
    enabled: own.length > 0,
    next: !own.every(isOn),
  }
}

/** Grants that differ from the last save, per role */
export function changes(saved: Grants, current: Grants) {
  const changed = new Set<string>()
  for (const role of roles) {
    const a = saved[role.id] ?? new Set<string>()
    const b = current[role.id] ?? new Set<string>()
    for (const k of a) if (!b.has(k)) changed.add(`${role.id}:${k}`)
    for (const k of b) if (!a.has(k)) changed.add(`${role.id}:${k}`)
  }
  return changed
}

export const actionLabel = Object.fromEntries(
  actions.map((a) => [a.id, a.label]),
) as Record<Action, string>

export function describe(state: CellState) {
  switch (state.kind) {
    case 'unavailable':
      return 'Not available for this resource'
    case 'locked':
      return `${state.role.name} always has every permission`
    case 'inherited':
      return `Inherited from ${state.from.name}`
    case 'required': {
      const list = state.by.map((a) => actionLabel[a])
      return `Needed by ${list.join(' and ')}. Remove ${list.length > 1 ? 'those' : 'that'} first.`
    }
    case 'granted':
      return 'Granted'
    case 'denied':
      return 'Not granted'
  }
}

import { Checkbox } from '#/components/ui/checkbox'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '#/components/ui/tooltip'
import { cn } from '#/lib/utils'
import { describe } from './permissions'
import type { CellState, Summary } from './permissions'

// Inherited and locked grants read as "on, but not yours to change": a muted
// check instead of the solid one, so a glance at the matrix shows what this
// role adds on top of the role it inherits from.
const muted =
  'disabled:opacity-100 data-[state=checked]:border-transparent data-[state=checked]:bg-muted-foreground/25 data-[state=checked]:text-foreground data-[state=indeterminate]:border-transparent data-[state=indeterminate]:bg-muted-foreground/25 data-[state=indeterminate]:text-foreground dark:data-[state=checked]:bg-muted-foreground/30 dark:data-[state=indeterminate]:bg-muted-foreground/30'

export function PermissionCheckbox({
  state,
  label,
  changed,
  onChange,
}: {
  state: CellState
  /** e.g. "Edit Invoices" */
  label: string
  /** Differs from the last save */
  changed: boolean
  onChange: (on: boolean) => void
}) {
  if (state.kind === 'unavailable') {
    return (
      <span className="text-muted-foreground/50" title={describe(state)}>
        <span aria-hidden>–</span>
        <span className="sr-only">
          {label}: {describe(state)}
        </span>
      </span>
    )
  }

  const editable = state.kind === 'granted' || state.kind === 'denied'
  const checkbox = (
    <Checkbox
      checked={state.kind !== 'denied'}
      disabled={!editable}
      onCheckedChange={(checked) => onChange(checked === true)}
      aria-label={editable ? label : `${label}: ${describe(state)}`}
      className={cn(
        (state.kind === 'inherited' || state.kind === 'locked') && muted,
      )}
    />
  )

  return (
    <span className="relative inline-flex">
      {editable ? (
        checkbox
      ) : (
        // A disabled button gets no pointer events, so the tooltip hangs on a wrapper
        <Tooltip>
          <TooltipTrigger asChild>
            <span className="inline-flex">{checkbox}</span>
          </TooltipTrigger>
          <TooltipContent>{describe(state)}</TooltipContent>
        </Tooltip>
      )}
      {changed ? (
        <span
          aria-hidden
          className="absolute -top-1 -right-1 size-1.5 rounded-full bg-amber-500"
        />
      ) : null}
    </span>
  )
}

export function SummaryCheckbox({
  summary,
  label,
  onChange,
}: {
  summary: Summary
  label: string
  onChange: (on: boolean) => void
}) {
  return (
    <Checkbox
      checked={summary.checked}
      disabled={!summary.enabled}
      onCheckedChange={() => onChange(summary.next)}
      aria-label={label}
      className={cn(!summary.enabled && muted)}
    />
  )
}

import { ChevronRight } from 'lucide-react'
import type { ColumnDef, Table } from '@tanstack/react-table'

import { cn } from '#/lib/utils'
import { actions, resourceGroups } from './data'
import type { Action, Grants, Resource } from './data'
import { PermissionCheckbox, SummaryCheckbox } from './permission-checkbox'
import { cellState, key, summarize } from './permissions'
import type { Cell } from './permissions'

/** A group of resources, or one resource. Both carry the resources they cover. */
export interface MatrixRow {
  id: string
  name: string
  description?: string
  resources: Resource[]
  subRows?: MatrixRow[]
}

export const rows: MatrixRow[] = resourceGroups.map((group) => ({
  id: group.id,
  name: group.name,
  resources: group.resources,
  subRows: group.resources.map((resource) => ({
    id: `${group.id}/${resource.id}`,
    name: resource.name,
    description: resource.description,
    resources: [resource],
  })),
}))

const allResources = resourceGroups.flatMap((g) => g.resources)

export interface MatrixMeta {
  roleId: string
  grants: Grants
  /** `role:resource.action` keys that differ from the last save */
  changed: Set<string>
  setCells: (cells: Cell[], on: boolean) => void
}

const getMeta = (table: Table<MatrixRow>) =>
  table.options.meta as unknown as MatrixMeta

export const cellsFor = (
  resources: Resource[],
  only: readonly Action[] = actions.map((a) => a.id),
): Cell[] =>
  resources.flatMap((resource) => only.map((action) => ({ resource, action })))

export const columns: ColumnDef<MatrixRow>[] = [
  {
    id: 'resource',
    header: 'Resource',
    cell: ({ row }) =>
      row.getCanExpand() ? (
        <button
          type="button"
          onClick={row.getToggleExpandedHandler()}
          aria-expanded={row.getIsExpanded()}
          className="flex items-center gap-1.5 rounded-sm text-left font-medium outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
        >
          <ChevronRight
            className={cn(
              'size-4 text-muted-foreground transition-transform',
              row.getIsExpanded() && 'rotate-90',
            )}
          />
          {row.original.name}
          <span className="font-normal text-muted-foreground">
            {row.original.resources.length}
          </span>
        </button>
      ) : (
        <div className="flex min-w-0 flex-col pl-5.5">
          <span className="truncate">{row.original.name}</span>
          <span className="truncate text-xs text-muted-foreground">
            {row.original.description}
          </span>
        </div>
      ),
  },
  ...actions.map(({ id: action, label }): ColumnDef<MatrixRow> => ({
    id: action,
    header: ({ table }) => {
      const meta = getMeta(table)
      const cells = cellsFor(allResources, [action])
      return (
        <div className="flex flex-col items-center gap-1.5">
          <span>{label}</span>
          <SummaryCheckbox
            summary={summarize(meta.roleId, cells, meta.grants)}
            label={`${label} on every resource`}
            onChange={(on) => meta.setCells(cells, on)}
          />
        </div>
      )
    },
    cell: ({ row, table }) => {
      const meta = getMeta(table)
      const { resources, name } = row.original
      if (row.getCanExpand()) {
        const cells = cellsFor(
          resources.filter((r) => r.actions.includes(action)),
          [action],
        )
        if (!cells.length) return null
        return (
          <SummaryCheckbox
            summary={summarize(meta.roleId, cells, meta.grants)}
            label={`${label} on every ${name} resource`}
            onChange={(on) => meta.setCells(cells, on)}
          />
        )
      }
      const cell = { resource: resources[0], action }
      return (
        <PermissionCheckbox
          state={cellState(meta.roleId, cell, meta.grants)}
          label={`${label} ${name}`}
          changed={meta.changed.has(
            `${meta.roleId}:${key(resources[0].id, action)}`,
          )}
          onChange={(on) => meta.setCells([cell], on)}
        />
      )
    },
  })),
  {
    id: 'all',
    header: ({ table }) => {
      const meta = getMeta(table)
      const cells = cellsFor(allResources)
      return (
        <div className="flex flex-col items-center gap-1.5">
          <span>All</span>
          <SummaryCheckbox
            summary={summarize(meta.roleId, cells, meta.grants)}
            label="Every permission"
            onChange={(on) => meta.setCells(cells, on)}
          />
        </div>
      )
    },
    cell: ({ row, table }) => {
      const meta = getMeta(table)
      const cells = cellsFor(row.original.resources)
      return (
        <SummaryCheckbox
          summary={summarize(meta.roleId, cells, meta.grants)}
          label={`Every permission on ${row.original.name}`}
          onChange={(on) => meta.setCells(cells, on)}
        />
      )
    },
  },
]

import { useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type { ExpandedState } from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { TooltipProvider } from '#/components/ui/tooltip'
import { cn } from '#/lib/utils'
import { columns, rows } from './columns'
import type { MatrixMeta } from './columns'

export function PermissionsTable(meta: MatrixMeta) {
  const [expanded, setExpanded] = useState<ExpandedState>(true)

  const table = useReactTable({
    data: rows,
    columns,
    getRowId: (row) => row.id,
    getSubRows: (row) => row.subRows,
    getCoreRowModel: getCoreRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    state: { expanded },
    onExpandedChange: setExpanded,
    meta,
  })

  return (
    <TooltipProvider delayDuration={200}>
      <div className="overflow-x-auto rounded-md border">
        <Table className="min-w-[600px]">
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className="hover:bg-transparent">
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    className={cn(
                      'h-auto py-2.5',
                      header.column.id === 'resource'
                        ? 'sticky left-0 z-10 bg-background'
                        : 'w-20 text-center',
                      header.column.id === 'all' && 'border-l',
                    )}
                  >
                    {flexRender(
                      header.column.columnDef.header,
                      header.getContext(),
                    )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.map((row) => {
              const isGroup = row.getCanExpand()
              return (
                <TableRow
                  key={row.id}
                  // Cells paint the row color themselves: the pinned name column
                  // must be opaque, and this keeps it matching the cells beside it
                  className="group/row hover:bg-transparent has-aria-expanded:bg-transparent"
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      className={cn(
                        isGroup
                          ? 'bg-muted'
                          : 'bg-background group-hover/row:bg-[color-mix(in_oklab,var(--muted)_50%,var(--background))]',
                        cell.column.id === 'resource'
                          ? 'sticky left-0 z-10 max-w-40 sm:max-w-64'
                          : 'text-center [&>*]:align-middle',
                        cell.column.id === 'all' && 'border-l',
                      )}
                    >
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              )
            })}
          </TableBody>
        </Table>
      </div>
    </TooltipProvider>
  )
}
